WITH account_totals AS (SELECT account_id, COUNT(amount) AS amount_count, SUM(CASE WHEN merchant = 'Starbucks' THEN amount ELSE 0 END) AS starbucks_amount FROM transactions WHERE merchant IS NULL GROUP BY account_id) SELECT a.id, a.customer_id, a.account_type, at.amount_count, at.starbucks_amount FROM accounts a LEFT OUTER JOIN account_totals at ON a.id = at.account_id ORDER BY a.customer_id DESC, at.starbucks_amount DESC
